// 4 gray levels mapped to epdiy 16 levels: 0=Black, 5=Dark Gray, 10=Light Gray, 15=White
static const uint8_t kStockGray16[4] = {0, 5, 10, 15};

bool stock_wallpaper_draw(uint8_t *fb, EpdRect area) {
    if (!fb || area.width <= 0 || area.height <= 0) return false;

    // Fill background with white (15)
    epd_fill_rect(area, 15, fb);

    // Calculate aspect-preserving scale to fit or fill
    // If area is portrait (like full screen 684x1216), fit width and center vertically
    int target_w = area.width;
    int target_h = (target_w * STOCK_WALL_HEIGHT) / STOCK_WALL_WIDTH;

    int offset_x = area.x;
    int offset_y = area.y + (area.height - target_h) / 2;

    if (target_h > area.height) {
        target_h = area.height;
        target_w = (target_h * STOCK_WALL_WIDTH) / STOCK_WALL_HEIGHT;
        offset_x = area.x + (area.width - target_w) / 2;
        offset_y = area.y;
    }

    for (int dy = 0; dy < target_h; ++dy) {
        int py = offset_y + dy;
        if (py < area.y || py >= area.y + area.height) continue;

        int sy = (dy * STOCK_WALL_HEIGHT) / target_h;
        if (sy >= STOCK_WALL_HEIGHT) sy = STOCK_WALL_HEIGHT - 1;
        const uint8_t *row = &kStockWallpaper4Gray[sy * STOCK_WALL_STRIDE];

        for (int dx = 0; dx < target_w; ++dx) {
            int px = offset_x + dx;
            if (px < area.x || px >= area.x + area.width) continue;

            int sx = (dx * STOCK_WALL_WIDTH) / target_w;
            if (sx >= STOCK_WALL_WIDTH) sx = STOCK_WALL_WIDTH - 1;

            uint8_t byte_val = row[sx >> 2];
            uint8_t val = (byte_val >> (6 - ((sx & 3) * 2))) & 0x03;

            epd_draw_pixel(px, py, kStockGray16[val], fb);
        }
    }

    return true;
}
